"""
Agent launcher — manage AI coding agents in tmux sessions.

Provides launch, send, read, approve, kill capabilities for
Claude Code, OpenCode, and Codex agents running in tmux windows
within a shared tmux session.
"""

from __future__ import annotations

import logging
import shlex
import subprocess
import time
import uuid
from pathlib import Path
from typing import Callable, Optional

from .constants import TMUX_SESSION_NAME, TOOL_COMMANDS
from .exceptions import AgentLauncherError, AgentSessionNotFoundError
from .registry import AgentSessionRegistryManager
from .schemas import AgentSession, AgentStatus, AgentTool

logger = logging.getLogger(__name__)


def parse_github_url(url: str) -> dict[str, Optional[str]]:
    """Parse a GitHub URL or shorthand into components.

    Accepts:
        - ``https://github.com/org/repo``
        - ``https://github.com/org/repo/issues/42``
        - ``https://github.com/org/repo/pull/15``
        - ``org/repo`` (shorthand)
        - ``org/repo#42`` (issue shorthand)

    Returns:
        Dict with keys: ``repo`` (org/repo), ``clone_url``, ``issue``, ``pr``.
    """
    import re

    result: dict[str, Optional[str]] = {
        "repo": None,
        "clone_url": None,
        "issue": None,
        "pr": None,
    }

    url = url.strip()

    # Full GitHub URL
    gh_match = re.match(
        r"https?://github\.com/([^/]+/[^/]+?)(?:\.git)?(?:/(issues|pull)/(\d+))?/?$",
        url,
    )
    if gh_match:
        result["repo"] = gh_match.group(1)
        result["clone_url"] = f"https://github.com/{gh_match.group(1)}.git"
        if gh_match.group(2) == "issues":
            result["issue"] = gh_match.group(3)
        elif gh_match.group(2) == "pull":
            result["pr"] = gh_match.group(3)
        return result

    # Shorthand: org/repo or org/repo#42
    short_match = re.match(r"^([^/\s]+/[^/\s#]+)(?:#(\d+))?$", url)
    if short_match:
        result["repo"] = short_match.group(1)
        result["clone_url"] = f"https://github.com/{short_match.group(1)}.git"
        if short_match.group(2):
            result["issue"] = short_match.group(2)
        return result

    return result


def clone_repo(
    clone_url: str,
    target_dir: Path,
    repo_name: str,
    progress_callback: Optional[Callable[[str], None]] = None,
) -> Path:
    """Clone a GitHub repo into target_dir/repo_name.

    Args:
        clone_url: Git clone URL.
        target_dir: Parent directory to clone into.
        repo_name: Name for the cloned directory.
        progress_callback: Optional callable that receives progress lines
            from ``git clone --progress``. Called with each stderr line.
            If None, clone runs silently.

    Returns:
        The path to the cloned directory.

    Raises:
        AgentLauncherError: If the clone fails.
    """
    dest = target_dir / repo_name
    if dest.exists():
        logger.info("Repo already exists at %s, skipping clone", dest)
        if progress_callback:
            progress_callback(f"Repository already exists at {dest}")
        return dest

    cmd = ["git", "clone", "--progress", clone_url, str(dest)]

    if progress_callback:
        progress_callback(f"Cloning {clone_url}...")
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        # Git progress goes to stderr
        if proc.stderr is None:
            raise AgentLauncherError("git clone: stderr pipe unexpectedly None")
        for line in iter(proc.stderr.readline, ""):
            line = line.strip()
            if line:
                progress_callback(line)
        proc.wait()
        if proc.returncode != 0:
            stdout = proc.stdout.read() if proc.stdout else ""
            raise AgentLauncherError(f"git clone failed: {stdout.strip()}")
    else:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
        if result.returncode != 0:
            raise AgentLauncherError(
                f"git clone failed: {result.stderr.strip() or result.stdout.strip()}"
            )

    logger.info("Cloned %s to %s", clone_url, dest)
    return dest


def list_github_repos(limit: int = 50) -> list[str]:
    """List the user's GitHub repos using the gh CLI.

    Returns a list of ``org/repo`` strings, or empty list if gh is
    unavailable or not authenticated.
    """
    try:
        result = subprocess.run(
            ["gh", "repo", "list", "--limit", str(limit), "--json", "nameWithOwner"],
            capture_output=True,
            text=True,
            check=False,
            timeout=10,
        )
        if result.returncode != 0:
            return []
        import json

        data = json.loads(result.stdout)
        return [r["nameWithOwner"] for r in data]
    except (FileNotFoundError, subprocess.TimeoutExpired, Exception):
        return []


# Map tool command strings to AgentTool enum values
_TOOL_ENUM_MAP: dict[str, AgentTool] = {
    "claude": AgentTool.CLAUDE,
    "claude-auto": AgentTool.CLAUDE,
    "codeq": AgentTool.CODEQ,
    "codex": AgentTool.CODEX,
}


def check_tmux_available() -> bool:
    """Check if tmux is installed and accessible."""
    try:
        subprocess.run(["tmux", "-V"], capture_output=True, check=True, timeout=5)
        return True
    except (FileNotFoundError, subprocess.CalledProcessError, subprocess.TimeoutExpired):
        return False


def require_tmux() -> None:
    """Raise AgentLauncherError if tmux is not installed."""
    if not check_tmux_available():
        import platform

        system = platform.system().lower()
        if system == "darwin":
            install_cmd = "brew install tmux"
        elif system == "linux":
            install_cmd = "sudo apt install tmux  # or: sudo yum install tmux"
        else:
            install_cmd = "See https://github.com/tmux/tmux/wiki/Installing"

        raise AgentLauncherError(
            f"tmux is not installed. Agent launching requires tmux.\n\n"
            f"Install with:\n  {install_cmd}\n\n"
            f"Then try again."
        )


class AgentLauncher:
    """Launch and control AI coding agents in tmux sessions."""

    def __init__(
        self,
        registry: Optional[AgentSessionRegistryManager] = None,
        tmux_session: str = TMUX_SESSION_NAME,
    ):
        require_tmux()
        self._registry = registry or AgentSessionRegistryManager()
        self._tmux_session = tmux_session

    # -- internal helpers ----------------------------------------------------

    @staticmethod
    def _run(
        cmd: list[str], check: bool = True, capture: bool = True
    ) -> subprocess.CompletedProcess:
        """Run a subprocess command.

        Args:
            cmd: Command and arguments to execute.
            check: If True, raise CalledProcessError on non-zero exit.
            capture: If True, capture stdout and stderr.

        Returns:
            Completed process result.
        """
        return subprocess.run(
            cmd,
            capture_output=capture,
            text=True,
            check=check,
        )

    def _find_available_port(self) -> Optional[int]:
        """Find an available port in the OpenCode port range.

        Checks which ports are already used by active sessions in the
        registry, then returns the first free one.
        """
        from .constants import OPENCODE_PORT_RANGE_END, OPENCODE_PORT_RANGE_START

        # Collect ports already in use
        used_ports = set()
        try:
            registry = self._registry.load_registry()
            for s in registry.sessions:
                if s.port and s.status.value not in ("stopped", "error"):
                    used_ports.add(s.port)
        except Exception:
            pass

        # Find first available
        import socket

        for port in range(OPENCODE_PORT_RANGE_START, OPENCODE_PORT_RANGE_END + 1):
            if port in used_ports:
                continue
            # Verify port is actually free on the network
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                    sock.bind(("127.0.0.1", port))
            except OSError:
                continue  # Port in use, try next
            return port

        logger.warning(
            "No available ports in range %d-%d", OPENCODE_PORT_RANGE_START, OPENCODE_PORT_RANGE_END
        )
        return None

    def _ensure_tmux_session(self) -> None:
        """Create the shared tmux session if it does not already exist."""
        result = self._run(["tmux", "has-session", "-t", self._tmux_session], check=False)
        if result.returncode != 0:
            self._run(
                [
                    "tmux",
                    "new-session",
                    "-d",
                    "-s",
                    self._tmux_session,
                    "-n",
                    "_control",
                ]
            )
            logger.info("Created tmux session '%s'", self._tmux_session)

    def _tmux_target(self, window: str) -> str:
        """Return the tmux target string for a window in the managed session."""
        return f"{self._tmux_session}:{window}"

    def _resolve_session(self, session_id: str) -> AgentSession:
        """Find a session by ID or prefix and validate it has tmux info.

        Supports prefix matching: if ``session_id`` is shorter than a full UUID,
        it will match the first session whose ID starts with that prefix.

        Args:
            session_id: Full session ID or unique prefix.

        Returns:
            The matched AgentSession.

        Raises:
            AgentSessionNotFoundError: If no session matches the ID/prefix.
            AgentLauncherError: If the session has no tmux window set.
        """
        # Try exact match first
        try:
            session = self._registry.get_session(session_id)
        except AgentSessionNotFoundError as exc:
            session = None
            registry = self._registry.load_registry()

            # Try prefix match on session_id
            matches = [s for s in registry.sessions if s.session_id.startswith(session_id)]

            # If no session_id match, try matching by name (tmux_window or terminal_name)
            if not matches:
                matches = [
                    s
                    for s in registry.sessions
                    if (s.tmux_window and s.tmux_window == session_id)
                    or (s.terminal_name and s.terminal_name == session_id)
                ]

            if len(matches) == 1:
                session = matches[0]
            elif len(matches) > 1:
                ids = [
                    f"{s.session_id[:8]} ({s.tmux_window or s.terminal_name or '?'})"
                    for s in matches
                ]
                raise AgentLauncherError(
                    f"Ambiguous match for '{session_id}', " f"matches: {', '.join(ids)}"
                ) from exc
            else:
                raise AgentSessionNotFoundError(
                    f"No session found matching '{session_id}'"
                ) from exc

        assert session is not None  # guaranteed by exception branches above

        if not session.tmux_window:
            raise AgentLauncherError(
                f"Session '{session.session_id}' has no tmux window set. "
                "It may not have been launched via AgentLauncher."
            )

        return session

    # -- public API ----------------------------------------------------------

    def launch(
        self,
        tool: str,
        cwd: Optional[str] = None,
        name: Optional[str] = None,
        instructions: Optional[str] = None,
        repo: Optional[str] = None,
        agent_type: Optional[str] = None,
        parent_session_id: Optional[str] = None,
        team_id: Optional[str] = None,
        tags: Optional[list[str]] = None,
        progress_callback: Optional[Callable[[str], None]] = None,
    ) -> AgentSession:
        """Launch an agent in a new tmux window.

        Creates a tmux window inside the managed session, optionally changes
        to the given working directory, then executes the tool command.

        Args:
            tool: Tool identifier (``"claude"``, ``"claude-auto"``, ``"codeq"``,
                  or ``"codex"``).
            cwd: Working directory for the agent. Defaults to the current directory.
            name: Window name. Auto-generated if not provided.
            instructions: Initial instructions to pass to the agent.
            repo: GitHub repo URL, shorthand (org/repo), or issue/PR URL.
                  Clones the repo into ``cwd`` and launches the agent there.
            agent_type: Agent type (leader, worker, observer, reviewer).
            parent_session_id: Parent session ID for team hierarchies.
            team_id: Team identifier for multi-agent coordination.
            tags: Optional list of tags for the session.

        Returns:
            The registered AgentSession.

        Raises:
            AgentLauncherError: If the tool is unknown, clone fails, or
                tmux operations fail.
        """
        # Handle GitHub repo: clone and adjust cwd/instructions
        gh_pr = None
        if repo:
            parsed = parse_github_url(repo)
            if not parsed["repo"] or not parsed["clone_url"]:
                raise AgentLauncherError(f"Could not parse GitHub URL: {repo}")

            target_dir = Path(cwd).expanduser().resolve() if cwd else Path.cwd()
            repo_name = parsed["repo"].split("/")[-1]

            # Use repo name as default agent name
            if name is None:
                name = repo_name

            # Clone (with progress callback if provided)
            cloned_path = clone_repo(
                parsed["clone_url"],
                target_dir,
                repo_name,
                progress_callback=progress_callback,
            )
            cwd = str(cloned_path)

            # Handle PR — pass to Claude's --from-pr flag
            if parsed["pr"] and tool in ("claude", "claude-auto"):
                gh_pr = parsed["pr"]

            # Handle issue — pass as instructions
            if parsed["issue"]:
                issue_url = f"https://github.com/{parsed['repo']}/issues/{parsed['issue']}"
                issue_instruction = f"Work on this GitHub issue: {issue_url}"
                instructions = (
                    f"{issue_instruction}\n{instructions}" if instructions else issue_instruction
                )

        tool_cmd = TOOL_COMMANDS.get(tool)
        if tool_cmd is None:
            raise AgentLauncherError(
                f"Unknown tool '{tool}'. Choose from: {', '.join(TOOL_COMMANDS)}"
            )

        tool_enum = _TOOL_ENUM_MAP.get(tool)
        if tool_enum is None:
            raise AgentLauncherError(f"No AgentTool mapping for '{tool}'.")

        self._ensure_tmux_session()

        # Generate and sanitize window name
        if name is None:
            name = f"{tool}-{str(uuid.uuid4())[:6]}"
        name = name.replace(".", "-").replace(":", "-").replace(" ", "-")

        # Ensure unique name — tmux can't target by name when duplicates exist
        existing_windows = self.list_windows()
        existing_names = {w.get("window_name") for w in existing_windows}
        if name in existing_names:
            suffix = 2
            while f"{name}-{suffix}" in existing_names:
                suffix += 1
            name = f"{name}-{suffix}"
            logger.info("Name already taken, using '%s'", name)

        # Resolve working directory
        resolved_cwd = str(Path(cwd).expanduser().resolve()) if cwd else None

        # Pre-generate session ID so the hook can merge into this entry
        session_id = str(uuid.uuid4())

        try:
            # Create a new window inside the managed tmux session
            self._run(["tmux", "new-window", "-t", self._tmux_session, "-n", name])
            # Disable automatic-rename so Claude/OpenCode don't override our name
            self._run(
                ["tmux", "set-option", "-t", self._tmux_target(name), "automatic-rename", "off"],
                check=False,
            )
            # Brief pause to let tmux register the new window
            time.sleep(0.3)

            # Set QBRAID_SESSION_ID env var BEFORE launching the tool
            # so the hook's register command picks it up and merges
            self._run(
                [
                    "tmux",
                    "send-keys",
                    "-t",
                    self._tmux_target(name),
                    f"export QBRAID_SESSION_ID={session_id}",
                    "Enter",
                ]
            )
            time.sleep(0.2)

            # Change directory if specified
            if resolved_cwd:
                self._run(
                    [
                        "tmux",
                        "send-keys",
                        "-t",
                        self._tmux_target(name),
                        f"cd {shlex.quote(resolved_cwd)}",
                        "Enter",
                    ]
                )
                time.sleep(0.3)

            # Build launch command with --name flag for tools that support it
            full_cmd = tool_cmd
            assigned_port = None
            if tool in ("claude", "claude-auto"):
                escaped_name = name.replace('"', '\\"')
                full_cmd = f'{tool_cmd} --name "{escaped_name}"'
                if gh_pr:
                    full_cmd = f"{full_cmd} --from-pr {gh_pr}"
            elif tool == "codeq":
                # Assign a port for OpenCode's HTTP API
                assigned_port = self._find_available_port()
                if assigned_port:
                    full_cmd = f"{tool_cmd} --port {assigned_port}"

            # Ensure Claude trusts the workspace (create .claude/settings.local.json)
            if tool in ("claude", "claude-auto") and resolved_cwd:
                trust_dir = Path(resolved_cwd) / ".claude"
                trust_file = trust_dir / "settings.local.json"
                if not trust_file.exists():
                    try:
                        trust_dir.mkdir(parents=True, exist_ok=True)
                        trust_file.write_text('{"permissions": {"allow": []}}')
                        logger.info("Created trust file at %s", trust_file)
                    except OSError as e:
                        logger.debug("Could not create trust file: %s", e)

            # Launch the tool (always interactive — no -p flag)
            self._run(
                [
                    "tmux",
                    "send-keys",
                    "-t",
                    self._tmux_target(name),
                    full_cmd,
                    "Enter",
                ]
            )

            # If instructions provided, wait for the tool to start then
            # send as the first message (keeps the session interactive)
            if instructions:
                time.sleep(5)
                self._run(
                    [
                        "tmux",
                        "send-keys",
                        "-t",
                        self._tmux_target(name),
                        "-l",
                        instructions,
                    ]
                )
                self._run(
                    [
                        "tmux",
                        "send-keys",
                        "-t",
                        self._tmux_target(name),
                        "Enter",
                    ]
                )

            logger.info("Launched '%s' in tmux window '%s'", tool, name)

            # Grab the pane PID
            pid_result = self._run(
                [
                    "tmux",
                    "list-panes",
                    "-t",
                    self._tmux_target(name),
                    "-F",
                    "#{pane_pid}",
                ],
                check=False,
            )
            pane_pid = 0
            if pid_result.returncode == 0 and pid_result.stdout.strip():
                try:
                    pane_pid = int(pid_result.stdout.strip().splitlines()[0])
                except ValueError:
                    pass

        except subprocess.CalledProcessError as exc:
            raise AgentLauncherError(
                f"Failed to launch '{tool}' in tmux: {exc.stderr or exc}"
            ) from exc

        # Build and register the session
        session = AgentSession(
            session_id=session_id,
            tool=tool_enum,
            pid=pane_pid,
            status=AgentStatus.IDLE,
            cwd=resolved_cwd or str(Path.cwd()),
            port=assigned_port,
            tmux_session=self._tmux_session,
            tmux_window=name,
            agent_type=agent_type,
            parent_session_id=parent_session_id,
            team_id=team_id,
            tags=tags or [],
            started_at=time.time(),
        )

        self._registry.register_session(session)
        logger.info(
            "Registered session '%s' (tool=%s, window=%s, pid=%d)",
            session.session_id,
            tool,
            name,
            pane_pid,
        )

        return session

    def resume(
        self,
        session_id: str,
        name: Optional[str] = None,
    ) -> AgentSession:
        """Resume an existing session in a new managed tmux window.

        Looks up the session from the registry, determines the tool and
        native session ID, then launches the tool's resume command in a
        new tmux window. Updates the registry entry with tmux info so the
        session becomes fully managed.

        Args:
            session_id: Session ID, prefix, or name to resume.
            name: Optional tmux window name. Defaults to the existing
                terminal_name or tmux_window, or auto-generated.

        Returns:
            The updated AgentSession with tmux info.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If the tool doesn't support resume or
                tmux operations fail.
        """
        # Find matching sessions (by id, prefix, or name)
        registry = self._registry.load_registry()
        matches = [
            s
            for s in registry.sessions
            if (
                s.session_id == session_id
                or s.session_id.startswith(session_id)
                or (s.tmux_window and s.tmux_window == session_id)
                or (s.terminal_name and s.terminal_name == session_id)
            )
        ]

        if not matches:
            raise AgentSessionNotFoundError(f"No session found matching '{session_id}'")

        if len(matches) > 1:
            raise AgentLauncherError(
                f"Multiple sessions match '{session_id}'. "
                f"Use a more specific ID or the interactive picker."
            )

        session = matches[0]

        # Check if session is active in tmux
        if (
            session.tmux_session
            and session.tmux_window
            and session.status not in (AgentStatus.STOPPED, AgentStatus.ERROR)
        ):
            # Verify tmux window actually exists
            windows = self.list_windows()
            if any(w.get("window_name") == session.tmux_window for w in windows):
                raise AgentLauncherError(
                    f"ACTIVE_SESSION:{session.session_id}"
                    f":{session.tmux_session}:{session.tmux_window}"
                )

        # Determine tool and native session ID for resume command
        tool_value = session.tool.value if session.tool else "claude"

        # The native session ID is the transcript file stem (for Claude)
        # or the session_id itself
        native_sid = session.session_id
        if session.transcript_path:
            from pathlib import PurePosixPath

            native_sid = PurePosixPath(session.transcript_path).stem

        # Determine window name FIRST (needed for --name flag)
        if name is None:
            name = session.terminal_name or session.tmux_window
        if name is None:
            name = f"{tool_value}-{session.session_id[:6]}"
        # Sanitize: replace chars that break tmux targeting
        name = name.replace(".", "-").replace(":", "-").replace(" ", "-")

        # Build resume command per tool

        escaped_name = shlex.quote(name)
        resume_commands = {
            "claude": f"claude --resume {native_sid} --name {escaped_name}",
            "codeq": f"opencode --session {native_sid}",
            "codex": f"codex resume {native_sid}",
        }
        resume_cmd = resume_commands.get(tool_value)
        if resume_cmd is None:
            raise AgentLauncherError(f"Resume is not supported for tool '{tool_value}'.")

        self._ensure_tmux_session()

        # Ensure unique window name
        existing_windows = self.list_windows()
        existing_names = {w.get("window_name") for w in existing_windows}
        if name in existing_names:
            suffix = 2
            while f"{name}-{suffix}" in existing_names:
                suffix += 1
            name = f"{name}-{suffix}"

        # Resolve cwd from the original session
        cwd = session.cwd

        try:
            # Create tmux window
            self._run(["tmux", "new-window", "-t", self._tmux_session, "-n", name])
            self._run(
                ["tmux", "set-option", "-t", self._tmux_target(name), "automatic-rename", "off"],
                check=False,
            )
            time.sleep(0.3)

            # Generate a NEW session ID for the resumed session — it's a fork,
            # not a continuation. The original session may still be running.
            new_session_id = str(uuid.uuid4())
            self._run(
                [
                    "tmux",
                    "send-keys",
                    "-t",
                    self._tmux_target(name),
                    f"export QBRAID_SESSION_ID={new_session_id}",
                    "Enter",
                ]
            )
            time.sleep(0.2)

            # cd to original working directory
            if cwd:
                self._run(
                    [
                        "tmux",
                        "send-keys",
                        "-t",
                        self._tmux_target(name),
                        f"cd {shlex.quote(cwd)}",
                        "Enter",
                    ]
                )
                time.sleep(0.3)

            # Run the resume command
            self._run(
                [
                    "tmux",
                    "send-keys",
                    "-t",
                    self._tmux_target(name),
                    resume_cmd,
                    "Enter",
                ]
            )

            logger.info(
                "Resumed session '%s' (%s) in tmux window '%s'",
                session.session_id,
                tool_value,
                name,
            )

            # Grab pane PID
            pid_result = self._run(
                [
                    "tmux",
                    "list-panes",
                    "-t",
                    self._tmux_target(name),
                    "-F",
                    "#{pane_pid}",
                ],
                check=False,
            )
            pane_pid = 0
            if pid_result.returncode == 0 and pid_result.stdout.strip():
                try:
                    pane_pid = int(pid_result.stdout.strip().splitlines()[0])
                except ValueError:
                    pass

        except subprocess.CalledProcessError as exc:
            raise AgentLauncherError(
                f"Failed to resume session in tmux: {exc.stderr or exc}"
            ) from exc

        # Register as a NEW session (it's a fork of the original)
        new_session = AgentSession(
            session_id=new_session_id,
            tool=session.tool,
            pid=pane_pid,
            status=AgentStatus.IDLE,
            cwd=cwd,
            tmux_session=self._tmux_session,
            tmux_window=name,
            agent_type=session.agent_type,
            team_id=session.team_id,
            tags=session.tags,
            started_at=time.time(),
        )
        self._registry.register_session(new_session)
        return new_session

    def resolve_native_session_id(self, session_id: str) -> Optional[str]:
        """Resolve the native session ID for an OpenCode session.

        OpenCode uses its own session IDs (ses_XXXX) internally.
        This method finds the most recent native session matching
        the agent's CWD from the OpenCode HTTP API and caches it
        in the registry's metadata field.

        Returns None for non-OpenCode sessions.
        """
        session = self._resolve_session(session_id)
        if session.tool != AgentTool.CODEQ or not session.port:
            return None

        # Check if already cached in metadata
        cached = session.metadata.get("opencode_session_id")
        if cached:
            return cached

        # Resolve from API
        try:
            from .opencode_api import list_opencode_sessions

            oc_sessions = list_opencode_sessions(session.port)
            native_id = None
            for ocs in oc_sessions:
                if ocs.get("directory") == session.cwd:
                    native_id = ocs["id"]
                    break
            if not native_id and oc_sessions:
                native_id = oc_sessions[0]["id"]

            # Cache it
            if native_id:
                try:
                    self._registry.update_session(
                        session.session_id,
                        metadata={**session.metadata, "opencode_session_id": native_id},
                    )
                except Exception:
                    pass
            return native_id
        except Exception:
            return None

    def send(self, session_id: str, text: str) -> None:
        """Send text followed by Enter to a running agent.

        For OpenCode sessions with a port, sends via HTTP API.
        For Claude/Codex, sends via tmux send-keys.

        Args:
            session_id: Session ID or unique prefix.
            text: Text to send.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info or send fails.
        """
        session = self._resolve_session(session_id)
        assert session.tmux_window is not None

        # OpenCode: use HTTP API
        if session.tool == AgentTool.CODEQ and session.port:
            native_id = self.resolve_native_session_id(session_id)
            if native_id:
                try:
                    from .opencode_api import send_opencode_message

                    if send_opencode_message(session.port, native_id, text):
                        return
                except Exception:
                    pass
            # Fallback to tmux if API fails
            logger.debug("OpenCode API send failed, falling back to tmux")

        try:
            self._run(
                [
                    "tmux",
                    "send-keys",
                    "-t",
                    self._tmux_target(session.tmux_window),
                    text,
                    "Enter",
                ]
            )
        except subprocess.CalledProcessError as exc:
            raise AgentLauncherError(
                f"Failed to send text to session '{session_id}': {exc.stderr or exc}"
            ) from exc

    def send_raw(self, session_id: str, text: str) -> None:
        """Send literal text without appending Enter.

        Useful for single-character confirmations or partial input.

        Args:
            session_id: Session ID or unique prefix.
            text: Raw text to send.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info or send fails.
        """
        session = self._resolve_session(session_id)
        assert session.tmux_window is not None
        try:
            self._run(
                [
                    "tmux",
                    "send-keys",
                    "-t",
                    self._tmux_target(session.tmux_window),
                    "-l",
                    text,
                ]
            )
        except subprocess.CalledProcessError as exc:
            raise AgentLauncherError(
                f"Failed to send raw text to session '{session_id}': " f"{exc.stderr or exc}"
            ) from exc

    def approve(self, session_id: str) -> None:
        """Approve a tool-use confirmation prompt by sending 'y' + Enter.

        Args:
            session_id: Session ID or unique prefix.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info or send fails.
        """
        session = self._resolve_session(session_id)
        assert session.tmux_window is not None
        target = self._tmux_target(session.tmux_window)
        try:
            self._run(["tmux", "send-keys", "-t", target, "-l", "y"])
            time.sleep(0.1)
            self._run(["tmux", "send-keys", "-t", target, "Enter"])
        except subprocess.CalledProcessError as exc:
            raise AgentLauncherError(
                f"Failed to send approval to session '{session_id}': " f"{exc.stderr or exc}"
            ) from exc

    def read(self, session_id: str, lines: int = 50) -> str:
        """Capture recent terminal output from an agent's tmux pane.

        Args:
            session_id: Session ID or unique prefix.
            lines: Number of lines to capture from the bottom of the pane.

        Returns:
            Captured pane content as a string.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info or capture fails.
        """
        session = self._resolve_session(session_id)
        assert session.tmux_window is not None
        result = self._run(
            [
                "tmux",
                "capture-pane",
                "-t",
                self._tmux_target(session.tmux_window),
                "-p",
                "-S",
                str(-lines),
            ],
            check=False,
        )
        if result.returncode != 0:
            raise AgentLauncherError(
                f"Failed to read from session '{session_id}': " f"{result.stderr.strip()}"
            )
        return result.stdout

    def check_alive(self, session_id: str) -> bool:
        """Check whether the tmux window for a session still exists.

        Args:
            session_id: Session ID or unique prefix.

        Returns:
            True if the window exists, False otherwise.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info.
        """
        session = self._resolve_session(session_id)
        result = self._run(
            [
                "tmux",
                "list-windows",
                "-t",
                self._tmux_session,
                "-F",
                "#{window_name}",
            ],
            check=False,
        )
        if result.returncode != 0:
            return False
        window_names = result.stdout.strip().splitlines()
        return session.tmux_window in window_names

    def kill(self, session_id: str) -> None:
        """Kill the tmux window for a session and mark it stopped.

        Args:
            session_id: Session ID or unique prefix.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info.
        """
        session = self._resolve_session(session_id)
        assert session.tmux_window is not None
        self._run(
            [
                "tmux",
                "kill-window",
                "-t",
                self._tmux_target(session.tmux_window),
            ],
            check=False,
        )
        logger.info(
            "Killed tmux window '%s' for session '%s'",
            session.tmux_window,
            session.session_id,
        )

        # Mark as stopped in the registry
        try:
            self._registry.update_session(
                session.session_id,
                status=AgentStatus.STOPPED,
                last_activity=time.time(),
            )
        except Exception as exc:
            logger.warning(
                "Failed to update registry after killing session '%s': %s",
                session.session_id,
                exc,
            )

    def get_pane_pid(self, session_id: str) -> Optional[int]:
        """Return the PID of the shell process in a session's tmux pane.

        Args:
            session_id: Session ID or unique prefix.

        Returns:
            The pane PID, or None if it cannot be determined.

        Raises:
            AgentSessionNotFoundError: If no session matches.
            AgentLauncherError: If session has no tmux info.
        """
        session = self._resolve_session(session_id)
        assert session.tmux_window is not None
        result = self._run(
            [
                "tmux",
                "list-panes",
                "-t",
                self._tmux_target(session.tmux_window),
                "-F",
                "#{pane_pid}",
            ],
            check=False,
        )
        if result.returncode == 0 and result.stdout.strip():
            try:
                return int(result.stdout.strip().splitlines()[0])
            except ValueError:
                return None
        return None

    def list_windows(self) -> list[dict[str, str]]:
        """List all windows in the managed tmux session.

        Returns:
            List of dicts with ``window_index``, ``window_name``,
            ``pane_pid``, and ``command`` keys.
        """
        result = self._run(
            [
                "tmux",
                "list-windows",
                "-t",
                self._tmux_session,
                "-F",
                "#{window_index} #{window_name} #{pane_pid} #{pane_current_command}",
            ],
            check=False,
        )
        if result.returncode != 0:
            return []

        entries: list[dict[str, str]] = []
        for line in result.stdout.strip().splitlines():
            parts = line.split(None, 3)
            if len(parts) >= 3:
                entries.append(
                    {
                        "window_index": parts[0],
                        "window_name": parts[1],
                        "pane_pid": parts[2],
                        "command": parts[3] if len(parts) > 3 else "",
                    }
                )
        return entries

    def prune_managed_sessions(self) -> list[str]:
        """Check all launcher-managed sessions and clean up dead ones.

        For each active session that has ``tmux_session`` and ``tmux_window``:
        - If the tmux window no longer exists, mark it stopped and kill it.
        - If the tmux window exists but the agent process exited (pane running
          shell instead of node/python), kill the window and mark stopped.

        Returns:
            List of session IDs that were pruned.
        """
        pruned: list[str] = []
        now = time.time()

        # Get all live tmux windows
        live_windows = self.list_windows()
        live_window_names = {w["window_name"] for w in live_windows}

        # Map window name -> current command for agent-alive detection
        window_commands = {w["window_name"]: w.get("command", "") for w in live_windows}

        registry = self._registry.load_registry()
        for session in registry.sessions:
            if session.status in (AgentStatus.STOPPED, AgentStatus.ERROR):
                continue
            if not session.tmux_session or not session.tmux_window:
                continue
            # Skip remote compute sessions — their tmux is on another machine
            if session.compute_id:
                continue
            if session.tmux_session != self._tmux_session:
                continue

            window = session.tmux_window

            # Window gone entirely
            if window not in live_window_names:
                try:
                    self._registry.update_session(
                        session.session_id,
                        status=AgentStatus.STOPPED,
                        last_activity=time.time(),
                    )
                    pruned.append(session.session_id)
                    logger.info(
                        "Pruned session '%s' — tmux window '%s' gone", session.session_id, window
                    )
                except Exception:
                    pass
                continue

            # Window exists but agent exited (shell running, not node/python)
            # Grace period: don't kill windows created less than 30s ago
            if session.started_at and (now - session.started_at) < 30:
                continue

            cmd = window_commands.get(window, "")
            agent_processes = {
                "node",
                "python",
                "python3",
                "opencode",
                "codex",
                "claude",
                ".opencode",
                "codeq",
                "codeq-bin",
            }
            if cmd and cmd not in agent_processes and window != "_control":
                # Kill the dead window and mark stopped
                self._run(
                    ["tmux", "kill-window", "-t", self._tmux_target(window)],
                    check=False,
                )
                try:
                    self._registry.update_session(
                        session.session_id,
                        status=AgentStatus.STOPPED,
                        last_activity=time.time(),
                    )
                    pruned.append(session.session_id)
                    logger.info(
                        "Pruned session '%s' — agent exited in window '%s'",
                        session.session_id,
                        window,
                    )
                except Exception:
                    pass

        return pruned

    # -- remote compute operations -------------------------------------------

    @staticmethod
    def _ssh_run(
        ssh_alias: str,
        remote_cmd: str,
        timeout: int = 30,
    ) -> subprocess.CompletedProcess:
        """Run a command on a remote compute server via SSH."""
        return subprocess.run(
            ["ssh", "-o", "ConnectTimeout=10", ssh_alias, remote_cmd],
            capture_output=True,
            text=True,
            check=False,
            timeout=timeout,
        )

    def remote_launch(
        self,
        ssh_alias: str,
        tool: str,
        cwd: Optional[str] = None,
        name: Optional[str] = None,
        instructions: Optional[str] = None,
        agent_type: Optional[str] = None,
        tags: Optional[list[str]] = None,
    ) -> AgentSession:
        """Launch an agent on a remote compute server via SSH.

        Runs ``qbraid agents launch`` on the remote machine, then creates
        a local registry entry with ``compute_id`` for tracking.

        Args:
            ssh_alias: SSH alias (e.g., ``qbraid-lab-v2-staging``).
            tool: Tool identifier.
            cwd: Working directory on the remote machine.
            name: Agent name.
            instructions: Initial instructions.
            agent_type: Agent type.
            tags: Tags.

        Returns:
            Local AgentSession with compute_id set.

        Raises:
            AgentLauncherError: If SSH or remote launch fails.
        """
        import json as _json

        # Build the remote qbraid agents launch command
        parts = ["qbraid", "agents", "launch", "--tool", tool]
        if cwd:
            parts.extend(["--cwd", cwd])
        if name:
            parts.extend(["--name", name])
        if agent_type:
            parts.extend(["--type", agent_type])
        if tags:
            for tag in tags:
                parts.extend(["--tag", tag])

        remote_cmd = " ".join(shlex.quote(p) for p in parts)

        logger.info("Remote launch on %s: %s", ssh_alias, remote_cmd)

        result = self._ssh_run(ssh_alias, remote_cmd, timeout=60)
        if result.returncode != 0:
            raise AgentLauncherError(
                f"Remote launch failed on {ssh_alias}: {result.stderr.strip()}"
            )

        # Parse the remote session info from output
        # The launch command outputs a Rich panel — extract session ID from it
        output = result.stdout
        remote_session_id = None
        remote_tmux_window = None
        for line in output.splitlines():
            if "Session ID:" in line:
                remote_session_id = line.split("Session ID:")[-1].strip().strip("│ ")
            if "Tmux Window:" in line:
                remote_tmux_window = line.split("Tmux Window:")[-1].strip().strip("│ ")

        if not remote_session_id:
            # Try to get it from the remote registry
            list_result = self._ssh_run(
                ssh_alias,
                "qbraid agents list --no-interactive --limit 1",
                timeout=15,
            )
            logger.debug("Remote list output: %s", list_result.stdout[:200])

        # Return a lightweight session object (NOT registered locally)
        tool_enum = _TOOL_ENUM_MAP.get(tool, AgentTool.CLAUDE)

        session = AgentSession(
            session_id=remote_session_id or str(uuid.uuid4()),
            tool=tool_enum,
            pid=0,
            status=AgentStatus.IDLE,
            cwd=cwd,
            compute_id=ssh_alias,
            terminal_name=name or remote_tmux_window,
            tmux_session="qbraid-agents",
            tmux_window=remote_tmux_window or name,
        )

        logger.info("Launched remote session on %s: %s", ssh_alias, session.session_id[:8])

        # Send instructions if provided (after agent starts)
        if instructions and remote_tmux_window:
            time.sleep(5)
            self.remote_send(ssh_alias, remote_tmux_window, instructions)

        return session

    def remote_send(
        self,
        ssh_alias: str,
        remote_session_id: str,
        text: str,
    ) -> bool:
        """Send text to an agent running on a remote compute server."""
        remote_cmd = (
            f"qbraid agents send {shlex.quote(remote_session_id)} --text {shlex.quote(text)}"
        )
        result = self._ssh_run(ssh_alias, remote_cmd, timeout=15)
        return result.returncode == 0

    def remote_read(
        self,
        ssh_alias: str,
        remote_session_id: str,
        lines: int = 50,
    ) -> str:
        """Read terminal output from a remote agent."""
        remote_cmd = f"qbraid agents read {shlex.quote(remote_session_id)} --lines {lines}"
        result = self._ssh_run(ssh_alias, remote_cmd, timeout=15)
        return result.stdout if result.returncode == 0 else f"Error: {result.stderr}"

    def remote_watch(
        self,
        ssh_alias: str,
        remote_session_id: str,
        initial_entries: int = 20,
    ):
        """Stream transcript entries from a remote agent via SSH.

        Runs ``qbraid agents watch --stream`` on the remote machine
        and yields parsed JSON events. Same interface as local
        ``watch_transcript`` — yields dicts with ``type``, ``content``,
        ``timestamp``, etc.

        This is useful for the frontend to show remote agent activity
        in the same dashboard as local agents.

        Args:
            ssh_alias: SSH alias for the remote compute server.
            remote_session_id: Session ID or name on the remote.
            initial_entries: Number of history entries to fetch first.

        Yields:
            Dict with event data (type, content, timestamp, tool_name, etc.)
        """
        import json as _json

        remote_cmd = (
            f"qbraid agents watch {shlex.quote(remote_session_id)} "
            f"--stream --lines {initial_entries}"
        )

        proc = subprocess.Popen(
            ["ssh", "-o", "ConnectTimeout=10", ssh_alias, remote_cmd],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )

        try:
            if proc.stdout is None:
                raise AgentLauncherError("SSH process stdout pipe unexpectedly None")
            for line in iter(proc.stdout.readline, ""):
                line = line.strip()
                if not line:
                    continue
                try:
                    event = _json.loads(line)
                    yield event
                except _json.JSONDecodeError:
                    pass
        except GeneratorExit:
            proc.terminate()
        finally:
            proc.terminate()
            try:
                proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill()

    def remote_list(
        self,
        ssh_alias: str,
        include_stopped: bool = False,
    ) -> list[AgentSession]:
        """List agents on a remote compute server.

        Uses ``qbraid agents list --json`` on the remote to get
        structured session data.

        Args:
            ssh_alias: SSH alias for the remote server.
            include_stopped: Include stopped sessions.

        Returns:
            List of AgentSession objects from the remote registry.
        """
        import json as _json

        flags = "qbraid agents list --json --no-interactive --limit 100"
        if include_stopped:
            flags += " --all"

        result = self._ssh_run(ssh_alias, flags, timeout=30)
        if result.returncode != 0:
            logger.warning("Remote list failed on %s: %s", ssh_alias, result.stderr[:200])
            return []

        try:
            data = _json.loads(result.stdout)
            sessions = []
            for entry in data:
                try:
                    session = AgentSession.model_validate(entry)
                    session.compute_id = ssh_alias
                    sessions.append(session)
                except Exception:
                    pass
            return sessions
        except _json.JSONDecodeError:
            logger.warning("Invalid JSON from remote list: %s", result.stdout[:200])
            return []

    def check_remote_alive(self, session_id: str) -> bool:
        """Check if a remote session's tmux window is still alive via SSH."""
        session = self._resolve_session(session_id)
        if not session.compute_id:
            return False

        ssh_alias = session.compute_id
        window = session.tmux_window
        if not window:
            return False

        result = self._ssh_run(
            ssh_alias,
            f"tmux list-windows -t qbraid-agents "
            f"-F '#{{window_name}}' 2>/dev/null "
            f"| grep -q '^{window}$'",
            timeout=10,
        )
        return result.returncode == 0

    def refresh_remote_sessions(self) -> list[str]:
        """Check all remote sessions and mark dead ones as stopped.

        For each active session with compute_id, SSHs in and checks
        if the tmux window is alive.

        Returns list of session IDs that were marked stopped.
        """
        pruned: list[str] = []
        registry = self._registry.load_registry()

        # Group by compute_id to minimize SSH calls
        remote_sessions: dict[str, list] = {}
        for s in registry.sessions:
            if s.compute_id and s.status not in (AgentStatus.STOPPED, AgentStatus.ERROR):
                remote_sessions.setdefault(s.compute_id, []).append(s)

        for ssh_alias, sessions in remote_sessions.items():
            # Get all windows on remote in one SSH call
            result = self._ssh_run(
                ssh_alias,
                "tmux list-windows -t qbraid-agents -F '#{window_name}' 2>/dev/null",
                timeout=10,
            )
            if result.returncode != 0:
                # Can't reach remote or no tmux session — mark all stopped
                for s in sessions:
                    try:
                        self._registry.update_session(
                            s.session_id,
                            status=AgentStatus.STOPPED,
                            last_activity=time.time(),
                        )
                        pruned.append(s.session_id)
                    except Exception:
                        pass
                continue

            live_windows = set(result.stdout.strip().splitlines())
            for s in sessions:
                if s.tmux_window and s.tmux_window not in live_windows:
                    try:
                        self._registry.update_session(
                            s.session_id,
                            status=AgentStatus.STOPPED,
                            last_activity=time.time(),
                        )
                        pruned.append(s.session_id)
                    except Exception:
                        pass

        if pruned:
            logger.info("Pruned %d dead remote sessions", len(pruned))
        return pruned

    def sync_remote_sessions(
        self,
        ssh_alias: str,
    ) -> list[AgentSession]:
        """Sync remote agent sessions into the local registry.

        SSHs into the compute server, discovers sessions, and creates
        local tracking entries with ``compute_id`` set.

        Returns list of synced sessions.
        """
        import json as _json

        # Run discover on the remote to refresh its registry
        self._ssh_run(ssh_alias, "qbraid agents discover 2>/dev/null", timeout=60)

        # Get remote sessions as JSON — we'll use a Python one-liner
        result = self._ssh_run(
            ssh_alias,
            'python3 -c "'
            "from qbraid_core.services.agents import AgentSessionRegistryManager;"
            "import json;"
            "r=AgentSessionRegistryManager();"
            "sessions=[s.model_dump(mode='json') for s in r.load_registry().sessions "
            "if s.status.value not in ('stopped','error')];"
            "print(json.dumps(sessions))"
            '"',
            timeout=30,
        )

        if result.returncode != 0:
            logger.warning(
                "Failed to sync remote sessions from %s: %s", ssh_alias, result.stderr[:200]
            )
            return []

        try:
            remote_sessions = _json.loads(result.stdout)
        except _json.JSONDecodeError:
            logger.warning("Invalid JSON from remote sync: %s", result.stdout[:200])
            return []

        synced: list[AgentSession] = []
        for remote_data in remote_sessions:
            # Create local tracking entry
            remote_sid = remote_data.get("sessionId", remote_data.get("session_id", ""))
            if not remote_sid:
                continue

            # Check if we already track this remote session
            existing = None
            for s in self._registry.load_registry().sessions:
                remote_meta_sid = (s.metadata or {}).get("remote_session_id", "")
                if remote_meta_sid == remote_sid and s.compute_id == ssh_alias:
                    existing = s
                    break

            if existing:
                # Update status
                try:
                    self._registry.update_session(
                        existing.session_id,
                        status=AgentStatus(remote_data.get("status", "idle")),
                        last_activity=time.time(),
                    )
                except Exception:
                    pass
                synced.append(existing)
            else:
                # Create new local entry
                tool_val = remote_data.get("tool", "claude")
                tool_enum = (
                    AgentTool(tool_val)
                    if tool_val in ("claude", "codeq", "codex")
                    else AgentTool.CLAUDE
                )

                session = AgentSession(
                    session_id=str(uuid.uuid4()),
                    tool=tool_enum,
                    pid=0,
                    status=AgentStatus(remote_data.get("status", "idle")),
                    cwd=remote_data.get("cwd"),
                    compute_id=ssh_alias,
                    terminal_name=remote_data.get("terminalName")
                    or remote_data.get("terminal_name"),
                    tmux_session=remote_data.get("tmuxSession") or remote_data.get("tmux_session"),
                    tmux_window=remote_data.get("tmuxWindow") or remote_data.get("tmux_window"),
                    model_name=remote_data.get("model"),
                    started_at=remote_data.get("startedAt") or remote_data.get("started_at"),
                    last_activity=time.time(),
                    metadata={
                        "remote_session_id": remote_sid,
                        "ssh_alias": ssh_alias,
                    },
                )
                self._registry.register_session(session)
                synced.append(session)

        logger.info("Synced %d sessions from %s", len(synced), ssh_alias)
        return synced
